-- TRUNCATE aflob_plan.lst_import_type;
INSERT INTO aflob_plan.lst_import_type(
	  guid											,beskrivelse											,aktiv	,dest_schema	,dest_table		,source_insert_columns																																																		,source_select
) VALUES
	 ('131c308a-3649-4039-b7fc-c6583ce7d98c'::uuid	,'KK + HOFOR - Bygværker'::character varying			,1		,'aflob_plan'	,'f_indhold_a'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_callout'																																		,EE'SELECT\n\tST_Union(dmp.geom) AS geom\n\t,''Eksisterende bygværk'' AS type\n\t,array_to_string(\n\t\tARRAY[\n\t\t\tCOALESCE(d.navn, '''')\n\t\t\t,''DK: '' || COALESCE(MAX(COALESCE(terraenkote, topkote_udvendig))::float::text, '''')\n\t\t\t,''BK: '' || COALESCE(MIN(bundkote_udvendig)::float::text, '''')\n\t\t]\n\t\t,E''\\\\n''\n\t) AS label\n\t,1 AS label_show\n\t,1 AS label_frame\n\t,1 AS label_callout\nFROM aflob.v_hofor_incl_kk_konstruktioner_a d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POLYGON''\n\n\tAND COALESCE(d.status, '''') NOT IN(\n\t\t''Fjernet''\n\t\t,''Død''\n\t\t,''Ikke i brug''\n\t\t,''Planlagt''\n\t)\n\nGROUP BY d.navn')
	,('1ba2f8e6-8778-4039-85fb-0b9427d3a136'::uuid	,'Parkeringsplads'::character varying					,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Parkeringsplads'' AS type\nFROM ctr.v_p_pladser d\n\t,ST_MakeValid(d.sdo_geometry) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''')
	,('26db72b5-95fb-4dd0-828e-9282598ec098'::uuid	,'Bygning'::character varying							,1		,'aflob_plan'	,'f_indhold_a'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Bygning'' AS type\nFROM datafordeleren.v_bygning_opr d\n\t,ST_MakeValid(d.geom) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POLYGON''')
	,('346339e0-8684-4db6-a559-3a5d47f812d7'::uuid	,'KK + HOFOR - Knuder'::character varying				,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_callout\n\n\t\t,aflob_tbl\n\t\t,aflob_guid\n\t\t,aflob_navn'																					,EE'SELECT\n\tdmp.geom\n\t,CASE\n\t\tWHEN d.knude_type IN(''Magasin'', ''Pumpested'', ''Tank'', ''Tilslutningspunkt'', ''Udløb'', ''Udskiller'')\n\t\tTHEN ''Punkt''\n\t\tWHEN d.nedloebsrist_bstk = ''Ja''\n\t\t\tOR COALESCE(d.ledning_kategori, ''Stikledning'') = ''Stikledning''\n\t\tTHEN ''Eksisterende rist''\n\t\tWHEN d.daeksel_bstk = ''Ja''\n\t\tTHEN ''Eksisterende dæksel''\n\t\tELSE ''Eksisterende dæksel''\n\tEND AS type\n\t,CASE\n\t\tWHEN d.knude_type IN(''Brønd'', ''Sandfang'')\n\t\t\tAND d.ledning_kategori IN(''Hovedledning'', ''Recipient'', ''Transportledning'')\n\t\tTHEN array_to_string(\n\t\t\t\tARRAY[\n\t\t\t\t\tCOALESCE(d.navn, '''')\n\t\t\t\t\t,''DK: '' || COALESCE(COALESCE(daeksel_kote, terraenkote, topkote)::float::text, '''')\n\t\t\t\t\t,''BK: '' || COALESCE(bundkote::float::text, '''')\n\t\t\t\t]\n\t\t\t\t,E''\\\\n''\n\t\t\t)\n\t\tELSE COALESCE(d.navn, '''')\n\tEND AS label\n\t,1 AS label_show\n\t,1 AS label_frame\n\t,1 AS label_callout\n\n\t,''f_knuder_p'' AS aflob_tbl\n\t,d.guid AS aflob_guid\n\t,d.navn AS aflob_navn\n\nFROM aflob.v_hofor_incl_kk_knuder_p d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE d.knude_type IN(''Brønd'', ''Magasin'', ''Pumpested'', ''Sandfang'', ''Tank'', ''Tilslutningspunkt'', ''Udløb'', ''Udskiller'')\n\tAND COALESCE(d.status, '''') NOT IN(\n\t\t''Fjernet''\n\t\t,''Død''\n\t\t,''Ikke i brug''\n\t\t,''Planlagt''\n\t)\n\tAND ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''\n\tAND CASE\n\t\t\tWHEN d.knude_type IN(''Tilslutningspunkt'')\n\t\t\tTHEN EXISTS(\n\t\t\t\t\tSELECT\n\t\t\t\t\t\t''1''\n\t\t\t\t\tFROM aflob.v_hofor_incl_kk_ledninger_l l\n\t\t\t\t\tWHERE COALESCE(l.status, '''') NOT IN(\n\t\t\t\t\t\t\t''Fjernet''\n\t\t\t\t\t\t\t,''Død''\n\t\t\t\t\t\t\t,''Ikke i brug''\n\t\t\t\t\t\t\t,''Planlagt''\n\t\t\t\t\t\t)\n\t\t\t\t\t\tAND COALESCE(l.ledning_kategori, '''') NOT IN(\n\t\t\t\t\t\t\t''Fiktiv ledning''\n\t\t\t\t\t\t) AND (\n\t\t\t\t\t\t\td.guid = l.starter_i_knude\n\t\t\t\t\t\t\tOR d.guid = l.slutter_i_knude\n\t\t\t\t\t\t)\n\t\t\t\t)\n\t\t\tELSE TRUE\n\t\tEND')
	,('3a1edc90-0138-4f08-9c2a-636697d11aa8'::uuid	,'Færdselstavle'::character varying						,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Færdselstavle'' AS type\nFROM ctr.v_trafikskilt d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.sdo_geometry), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.sdo_geometry, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''')
	,('4664dd47-931b-4308-8109-9f8f0916d4fa'::uuid	,'Stationering'::character varying						,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_frame_adjustment\n\t\t,label_frame_margin_left\n\t\t,label_frame_margin_right\n\t\t,label_frame_margin_top\n\t\t,label_frame_margin_bottom'	,E'SELECT\n\tdmp.geom\n\t,''Stationering'' AS type\n\t,d.distance AS label\n\t,1 AS label_show\n\t,0 AS label_frame\n\t,4 AS label_frame_adjustment\n\t,0.1 AS label_frame_margin_left\n\t,0.1 AS label_frame_margin_right\n\t,0.1 AS label_frame_margin_top\n\t,0.1 AS label_frame_margin_bottom\nFROM ctr.v_stationeringer_20m d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''')
	,('4ad1605e-0c80-48af-ad16-d2e924ce9570'::uuid	,'Adgangsadresse'::character varying					,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_frame_adjustment\n\t\t,label_frame_margin_left\n\t\t,label_frame_margin_right\n\t\t,label_frame_margin_top\n\t\t,label_frame_margin_bottom'	,E'SELECT\n\tdmp.geom\n\t,''Adgangsadresse'' AS type\n\t,d.husnr AS label\n\t,1 AS label_show\n\t,0 AS label_frame\n\t,4 AS label_frame_adjustment\n\t,0.1 AS label_frame_margin_left\n\t,0.1 AS label_frame_margin_right\n\t,0.1 AS label_frame_margin_top\n\t,0.1 AS label_frame_margin_bottom\nFROM segis2.f_dar_adgangsadresser d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''')
	,('54b432d0-9157-4705-a0c9-4cbb86852bff'::uuid	,'HOFOR - Bygværker (OLD)'::character varying			,1		,'aflob_plan'	,'f_indhold_a'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_callout'																																		,EE'SELECT\n\tST_Union(dmp.geom) AS geom\n\t,''Eksisterende bygværk'' AS type\n\t,COALESCE(d.bygvaerknavn, '''')\n\t\t|| E''\\\\nDK: '' || COALESCE(MAX(d.maxdaekselkote)::text, '''')\n\t\t|| E''\\\\nBK: '' || COALESCE(MIN(NULLIF(d.bundkote, -99))::text, '''') AS label\n\t,1 AS label_show\n\t,1 AS label_frame\n\t,1 AS label_callout\nFROM led.f_afl_kompleksbygvaerk_a d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POLYGON''\n\n\tAND d.datohistorisk IS NULL\n\tAND d.status NOT IN(\n\t\t''Fjernet''\n\t\t,''Fjernet (Sløjfet)''\n\t\t,''Død''\n\t\t,''Ikke i brug''\n\t\t,''Projekteret / planlagt''\n\t\t,''Planlagt''\n\t)\n\nGROUP BY d.bygvaerknavn')
	,('5ae31f60-e4d9-4112-bd34-22228c3e795e'::uuid	,'Helle'::character varying								,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Eksisterende forhold'' AS type\nFROM datafordeleren.v_helle d\n\t,ST_MakeValid(d.geom) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''')
