	,('63f2b985-41b9-4181-91c3-df54fe19d0af'::uuid	,'KK + HOFOR - Knuder (Kun brønde)'::character varying	,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_callout'																																		,EE'SELECT\n\tdmp.geom\n\t,CASE\n\t\tWHEN COALESCE(d.ledning_kategori, ''Stikledning'') = ''Stikledning''\n\t\tTHEN ''Eksisterende rist''\n\t\tELSE ''Eksisterende dæksel''\n\tEND AS type\n\t,array_to_string(\n\t\tARRAY[\n\t\t\tCOALESCE(d.navn, '''')\n\t\t\t,''DK: '' || COALESCE(COALESCE(daeksel_kote, terraenkote, topkote)::float::text, '''')\n\t\t\t,''BK: '' || COALESCE(bundkote::float::text, '''')\n\t\t]\n\t\t,E''\\\\n''\n\t) AS label\n\t,CASE\n\t\tWHEN d.ledning_kategori IN(''Hovedledning'', ''Recipient'')\n\t\tTHEN 1\n\t\tELSE 0\n\tEND AS label_show\n\t,1 AS label_frame\n\t,1 AS label_callout\nFROM aflob.v_hofor_incl_kk_knuder_p d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE d.knude_type IN(\n\t\t''Brønd''\n\t)\n\tAND COALESCE(d.status, '''') NOT IN(\n\t\t''Fjernet''\n\t\t,''Død''\n\t\t,''Ikke i brug''\n\t\t,''Planlagt''\n\t)\n\tAND ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''')
