	,('803a1f15-38d2-4e3a-8fa5-106152b49c2d'::uuid	,'Vandløbsmidte'::character varying						,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Vandløbsmidte'' AS type\nFROM datafordeleren.v_vandloebsmidte d\n\t,ST_MakeValid(d.geom) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''')
	,('88ded412-5f04-4225-b4df-eb5af93fdf0b'::uuid	,'Vejkant'::character varying							,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Eksisterende forhold'' AS type\nFROM datafordeleren.v_vejkant d\n\t,ST_MakeValid(d.geom) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''')
	,('8f663d77-bc34-4777-b0b0-6c953a719ee1'::uuid	,'Træ'::character varying								,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Træ'' AS type\nFROM datafordeleren.v_trae d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''')
	,('99214537-abdf-487b-94ed-69a06a180fa9'::uuid	,'HOFOR - Ledninger (OLD)'::character varying			,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_frame_adjustment\n\t\t,label_callout\n\n\t\t,flow_type'																						,E'SELECT\n\tdmp.geom\n\t,CASE\n\t\tWHEN d.tvaersnit = ''Åben kanal/vandløb''\n\t\tTHEN ''Åbent vandløb''\n\t\tELSE ''Eksisterende kloakledning''\n\tEND AS type\n\t,NULLIF(\n\t\tTRIM(\n\t\t\tCASE\n\t\t\t\tWHEN d.tvaersnit = ''Åben kanal/vandløb''\n\t\t\t\tTHEN ''Åbent vandløb''\n\t\t\t\tWHEN LOWER(d.roerbetegnelse) NOT IN(''uoplyst'')\n\t\t\t\tTHEN regexp_replace("roerbetegnelse", ''^(øj|ægf|v)'', ''ø'')\n\t\t\tEND\n\t\t)\n\t\t,''ø''\n\t) AS label\n\t,CASE\n\t\tWHEN d.kategoriafloeb = ''Stikledning''\n\t\t\t\tAND d.ejernavn = ''Vejvæsen''\n\t\t\tOR ST_Length(\n\t\t\t\tST_Intersection(\n\t\t\t\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t\t\t\t,[FRAME]\n\t\t\t\t)\n\t\t\t) <= 10\n\t\tTHEN 0\n\t\tELSE 1\n\tEND AS label_show\n\t,0 AS label_frame\n\t,7 AS label_frame_adjustment\n\t,1 AS label_callout\n\n\t,CASE\n\t\tWHEN d.tvaersnit = ''Åben kanal/vandløb''\n\t\tTHEN 0\n\t\tWHEN d.kategoriafloeb IN(''Hovedledning'', ''Recipient'')\n\t\t\tAND ST_Length(d.geom) >= 2\n\t\tTHEN 1\n\t\tELSE 0\n\tEND AS flow_type\nFROM led.f_alle_afl_ledninger_l d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''\n\n\tAND d.led_datohistorisk IS NULL\n\tAND d.del_datohistorisk IS NULL\n\tAND d.status NOT IN(\n\t\t''Fjernet''\n\t\t,''Fjernet (Sløjfet)''\n\t\t,''Død''\n\t\t,''Ikke i brug''\n\t\t,''Projekteret / planlagt''\n\t\t,''Planlagt''\n\t)\n\tAND d.roerbetegnelse NOT IN(\n\t\t''Fiktiv Bygværks Ledning''\n\t)')
	,('a8e45869-6fc0-433a-81f9-688215f75f8a'::uuid	,'Jordstykke'::character varying						,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Jordstykke'' AS type\nFROM (\n\t\tSELECT\n\t\t\tST_LineMerge(\n\t\t\t\tST_Split(\n\t\t\t\t\tST_Union(\n\t\t\t\t\t\tST_Intersection(\n\t\t\t\t\t\t\tST_ExteriorRing(dr.geom)\n\t\t\t\t\t\t\t,[FRAME]\n\t\t\t\t\t\t)\n\t\t\t\t\t)\n\t\t\t\t\t,ST_Union(dp.geom)\n\t\t\t\t)\n\t\t\t) AS geom\n\t\tFROM mat.f_kk_mu_jordstykke d\n\t\t\t,ST_MakeValid(d.geom) valid(geom)\n\t\t\t,ST_Dump(\n\t\t\t\tST_Transform(\n\t\t\t\t\tST_Force2D(valid.geom)\n\t\t\t\t\t,25832\n\t\t\t\t)\n\t\t\t) dmp\n\t\t\t,ST_DumpRings(dmp.geom) dr\n\t\t\t,ST_DumpPoints(dmp.geom) dp\n\t\tWHERE ST_IsValid(valid.geom)\n\t\t\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\t) i\n\t,ST_Dump(i.geom) dmp\nWHERE i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''')
	,('afa36b70-5ed8-4a82-83ae-3583553e0e25'::uuid	,'Afmærkning'::character varying						,1		,'aflob_plan'	,'f_indhold_a'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Eksisterende forhold'' AS type\nFROM ctr.f_afmaerkning d\n\t,ST_MakeValid(d.sdo_geometry) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POLYGON''\n\n\tAND d.type IN(\n\t\t''30'' -- Hvidafmærkning\n\t\t,''31'' -- Fodgængerfelt\n\t\t,''32'' -- Parkering\n\t\t,''50'' -- Servicemarkering\n\t\t,''60'' -- Pileafmærkning\n\t\t,''80'' -- Symboler på kørebane\n\t)')
	,('b4468887-018e-494c-98c6-6e32593df7f0'::uuid	,'HOFOR - Knuder (OLD)'::character varying				,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_callout'																																		,EE'SELECT\n\tdmp.geom\n\t,CASE\n\t\tWHEN d.kategoriafloeb = ''Stikledning''\n\t\t\tAND d.ejernavn = ''Vejvæsen''\n\t\tTHEN ''Eksisterende rist''\n\t\tELSE ''Eksisterende dæksel''\n\tEND AS type\n\t,COALESCE(d.knudenavn, '''')\n\t\t|| E''\\\\nDK: '' || COALESCE(d.mindaekselkote::text, '''')\n\t\t|| E''\\\\nBK: '' || COALESCE(NULLIF(d.bundkote, -99)::text, '''') AS label\n\t,CASE\n\t\tWHEN d.kategoriafloeb IN(''Hovedledning'', ''Recipient'')\n\t\tTHEN 1\n\t\tELSE 0\n\tEND AS label_show\n\t,1 AS label_frame\n\t,1 AS label_callout\nFROM led.f_alle_afl_knuder_p d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE d.knudetype = ''Brønd''\n\tAND d.datohistorisk IS NULL\n\tAND d.status NOT IN(\n\t\t''Fjernet''\n\t\t,''Fjernet (Sløjfet)''\n\t\t,''Død''\n\t\t,''Ikke i brug''\n\t\t,''Projekteret / planlagt''\n\t\t,''Planlagt''\n\t)\n\tAND ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''')
	,('cb4d6fd9-5d2f-41e7-839c-7bda3eab2a04'::uuid	,'Vejmidte Label'::character varying					,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_frame_adjustment\n\t\t,label_frame_margin_left\n\t\t,label_frame_margin_right\n\t\t,label_frame_margin_top\n\t\t,label_frame_margin_bottom'	,E'SELECT\n\tdmp.geom\n\t,''Vejmidte Label'' AS type\n\t,d.vejnavn AS label\n\t,1 AS label_show\n\t,0 AS label_frame\n\t,4 AS label_frame_adjustment\n\t,0.1 AS label_frame_margin_left\n\t,0.1 AS label_frame_margin_right\n\t,0.1 AS label_frame_margin_top\n\t,0.1 AS label_frame_margin_bottom\nFROM datafordeleren.v_vejmidte_geodk_labels d\n\t,ST_MakeValid(d.geom) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''\n\n\tAND d.kommunekode = ''0101''')
	,('cba7558a-42ff-4320-9cc0-6b7256530f80'::uuid	,'KK + HOFOR - Ledninger'::character varying			,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type\n\t\t,label\n\t\t,label_show\n\t\t,label_frame\n\t\t,label_frame_adjustment\n\t\t,label_callout\n\n\t\t,flow_type'																						,EE'SELECT\n\tdmp.geom\n\t,CASE\n\t\tWHEN d.roer_tvaerprofil = ''Frit tværprofil''\n\t\tTHEN ''Åbent vandløb''\n\t\tELSE ''Eksisterende kloakledning''\n\tEND AS type\n\t,CASE\n\t\tWHEN d.roer_tvaerprofil = ''Frit tværprofil''\n\t\tTHEN ''Åbent vandløb''\n\t\tWHEN roer_katalognr ~* ''\\\\d''\n\t\tTHEN roer_katalognr\n\tEND AS label\n\t,CASE\n\t\tWHEN COALESCE(d.ledning_kategori, ''Stikledning'') = ''Stikledning''\n\t\t\tOR ST_Length(dmp.geom) <= 10\n\t\tTHEN 0\n\t\tELSE 1\n\tEND AS label_show\n\t,0 AS label_frame\n\t,7 AS label_frame_adjustment\n\t,1 AS label_callout\n\n\t,CASE\n\t\tWHEN d.roer_tvaerprofil = ''Frit tværprofil''\n\t\tTHEN 0\n\t\tWHEN d.ledning_kategori IN(''Hovedledning'', ''Recipient'')\n\t\t\tAND ST_Length(d.geom) >= 2\n\t\tTHEN 1\n\t\tELSE 0\n\tEND AS flow_type\nFROM aflob.v_hofor_incl_kk_ledninger_l d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''\n\n\tAND COALESCE(d.status, '''') NOT IN(\n\t\t''Fjernet''\n\t\t,''Død''\n\t\t,''Ikke i brug''\n\t\t,''Planlagt''\n\t)\n\tAND COALESCE(d.ledning_kategori, '''') NOT IN(\n\t\t''Fiktiv ledning''\n\t)')
	,('faedacfc-be8a-4d77-a793-742b0ff5f8da'::uuid	,'Affaldskurv'::character varying						,1		,'aflob_plan'	,'f_indhold_p'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Affaldskurv''\nFROM cpn.v_affaldskurve_puma_kgb d\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(d.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''POINT''')
	,('fc4feb56-69e6-4819-8312-dc0c5cdd7297'::uuid	,'Parkering'::character varying							,1		,'aflob_plan'	,'f_indhold_l'	,E'geom\n\t\t,type'																																																			,E'SELECT\n\tdmp.geom\n\t,''Parkering'' AS type\nFROM datafordeleren.v_parkering d\n\t,ST_MakeValid(d.geom) valid(geom)\n\t,ST_Intersection(\n\t\tST_Transform(ST_Force2D(valid.geom), 25832)\n\t\t,[FRAME]\n\t) i(geom)\n\t,ST_Dump(i.geom) dmp\nWHERE ST_IsValid(valid.geom)\n\tAND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))\n\tAND i.geom IS NOT NULL\n\tAND NOT(ST_IsEmpty(i.geom))\n\tAND GeometryType(dmp.geom) = ''LINESTRING''')
;




